import numpy as np
from scipy.optimize import fsolve

def equation(vars, a_val, b_val):
    a, b, c = a_val, b_val, vars[0]
    if c <= 0: return 1e9
    lhs = (4*a)/(4*a**2 + 1) + (4*b)/(4*b**2 + 1) + (4*c)/(4*c**2 + 1)
    rhs = 1 / (2 * (a + b) * (b + c) * (c + a))
    return lhs - rhs

def find_s(a, b):
    c_initial = 1.0
    c_sol = fsolve(equation, [c_initial], args=(a, b))[0]
    if c_sol > 0:
        return a*b + b*c_sol + c_sol*a
    else:
        return None

