import numpy as np
from scipy.optimize import brentq

def find_S(S_guess):
    def equation_1d(a):
        c = (S_guess - a**2) / (2*a)
        if c <= 0:
            return 1e9
        lhs = a / (4*a**2 + 1) + a / (4*a**2 + 1) + c / (4*c**2 + 1)
        rhs = 1 / (8 * (2*a) * (a + c) * (a + c))
        return lhs - rhs

    try:
        max_a = np.sqrt(S_guess)
        if max_a <= 0.01: return None

        steps = 200
        xs = np.linspace(0.01, max_a - 0.01, steps)
        ys = [equation_1d(x) for x in xs]
        for i in range(len(ys)-1):
            if ys[i] * ys[i+1] < 0:
                root = brentq(equation_1d, xs[i], xs[i+1])
                return root
    except:
        pass
    return None

for s_test in [0.2, 0.25, 0.3, 0.4, 0.5]:
    root = find_S(s_test)
    print(f"S={s_test}, root={root}")

def f_m(u, m):
